# Baseline contract test for GET /api/recipes/{slug}.
# Asserts the recipe_servings response field is a floating-point number.
import os
import requests

BASE_URL = os.getenv("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")
TOKEN = os.getenv("SKYRAMP_TEST_TOKEN", "")
SLUG = os.getenv("SKYRAMP_TEST_RECIPE_SLUG", "test-recipe")


def test_recipe_summary_recipe_servings_is_float():
    headers = {"Authorization": f"Bearer {TOKEN}"} if TOKEN else {}
    resp = requests.get(f"{BASE_URL}/api/recipes/{SLUG}", headers=headers, timeout=10)
    assert resp.status_code == 200
    body = resp.json()
    # recipe_servings is serialized as a float (e.g. 2.5 servings)
    assert isinstance(body["recipe_servings"], float)
    assert body["slug"] == SLUG
